<div class="two-col wide-left"><section class="card pad stack"><h3>Create a request</h3><?php if(!$eligible): ?><p>No eligible orders at the moment.</p><?php else: ?><form method="post" id="request-form" class="stack"><?= csrf_field() ?><label>1. Select order<select id="request-order" required><?php foreach($eligible as $o): ?><option value="<?= e($o['order_no']) ?>" data-type="<?= $o['status']==='Delivered'?'return':'cancellation' ?>" <?= selected($_GET['no']??'',$o['order_no']) ?>>#<?= e($o['order_no']) ?> · <?= e($o['status']) ?> · <?= money($o['total']) ?></option><?php endforeach; ?></select></label><h4>2. Request type</h4><div class="flow-options"><label class="option-card"><input type="radio" name="request_type" value="cancellation" required>Cancellation</label><label class="option-card"><input type="radio" name="request_type" value="return" required>Return</label></div><p class="small muted">Returns are available for delivered orders only.</p><h4>3. Select a reason</h4><div id="request-reasons" class="flow-options"></div><label>Additional details (optional)<textarea name="description" rows="4" placeholder="Tell us a little more about your request…"></textarea></label><p class="small muted">Your order stays active until your cancellation request is approved.</p><button class="btn btn-block">Submit request</button></form><script>const rf=document.getElementById('request-form'),ro=document.getElementById('request-order');function rs(){const type=ro.selectedOptions[0].dataset.type;rf.action=<?= json_encode(url('order')) ?>+'&no='+encodeURIComponent(ro.value)+'&from=returns';rf.querySelectorAll('[name=request_type]').forEach(i=>{i.disabled=i.value!==type;i.checked=i.value===type});const reasons=type==='return'?['Incorrect item','Item arrived damaged','Quality issue','Other']:['Ordered by mistake','No longer needed','Incorrect delivery details','Other'];const box=document.getElementById('request-reasons');box.replaceChildren();reasons.forEach((r,n)=>{const l=document.createElement('label');l.className='option-card';const i=document.createElement('input');i.type='radio';i.name='reason';i.value=r;i.required=true;i.checked=n===0;l.append(i,r);box.append(l)})}ro.addEventListener('change',rs);rs();</script><?php endif; ?></section><aside class="stack"><section class="card pad flow-sage"><div class="row-between"><h3>Your requests</h3><small><?= count($reqs) ?> requests</small></div><?php foreach($reqs as $r): ?><div class="flow-request"><div class="row-between"><strong>#RC-<?= (int)$r['id'] ?></strong><?= status_badge($r['status']) ?></div><p><?= e(ucfirst($r['type']).' · Order '.$r['order_no']) ?><br>Reason: <?= e($r['reason']) ?></p><small>Submitted <?= e(date('d M Y',strtotime($r['created_at']))) ?></small><p><?= e($r['admin_remarks']??'') ?></p><a href="<?= url('order',['no'=>$r['order_no']]) ?>">View request details →</a></div><?php endforeach; if(!$reqs): ?><p>No requests yet.</p><?php endif; ?></section><section class="card pad"><h3>A little help with your request</h3><strong>Cancellations</strong><p>Choose an active eligible order. Your request will be reviewed.</p><strong>Returns</strong><p>Choose a delivered order. Please do not send items back unless instructed.</p><a href="<?= url('contact') ?>">Need help? Contact us →</a></section></aside></div>
